#include <string>
#include <vector>
#include <unordered_set>
#include <algorithm>

class Solution {
public:
    int maxFreqSum(std::string s) {
        std::unordered_set<char> vowels = {'a', 'e', 'i', 'o', 'u'};
        std::vector<int> v_count(26, 0);
        std::vector<int> c_count(26, 0);

        for (char ch : s) {
            if (vowels.count(ch)) {
                v_count[ch - 'a']++;
            } else {
                c_count[ch - 'a']++;
            }
        }

        int mv = 0, mc = 0;
        for (int i = 0; i < 26; ++i) {
            mv = std::max(mv, v_count[i]);
            mc = std::max(mc, c_count[i]);
        }
        return mv + mc;
    }
};

class Solution {
    public int maxFreqSum(String s) {
        int[] vCount = new int[26];
        int[] cCount = new int[26];
        String vowels = "aeiou";

        for (int i = 0; i < s.length(); ++i) {
            char ch = s.charAt(i);
            if (vowels.indexOf(ch) != -1) {
                vCount[ch - 'a']++;
            } else {
                cCount[ch - 'a']++;
            }
        }

        int mv = 0, mc = 0;
        for (int i = 0; i < 26; ++i) {
            if (vCount[i] > mv) mv = vCount[i];
            if (cCount[i] > mc) mc = cCount[i];
        }
        return mv + mc;
    }
}

