var maxFreqSum = function(s) {
    const vowels = new Set(['a', 'e', 'i', 'o', 'u']);
    const vCount = {};
    const cCount = {};

    for (const ch of s) {
        if (vowels.has(ch)) {
            vCount[ch] = (vCount[ch] || 0) + 1;
        } else {
            cCount[ch] = (cCount[ch] || 0) + 1;
        }
    }

    const mv = Object.values(vCount).length > 0 ? Math.max(...Object.values(vCount)) : 0;
    const mc = Object.values(cCount).length > 0 ? Math.max(...Object.values(cCount)) : 0;
    return mv + mc;
};
